#include <cstddef>
#include <list>
#include <string>
#include <unordered_map>
#include <utility>

// items: от новых к старым; pos — индекс items.
// Исходно индекс согласован, 0 < limit, size <= limit.
// Существующий ключ: ничего не менять.
// Новый: добавить первым, при заполнении удалить хвост.
// Один поток, промежуточное состояние не наблюдается.
// Hash, сравнения и деструкторы не бросают.
// Выделение памяти может бросить.
struct Cache {
  using Items = std::list<std::pair<int, std::string>>;
  Items items;
  std::unordered_map<int, Items::iterator> pos;
  std::size_t limit;

  void Put(int key, std::string value) {
    if (pos.contains(key)) return;
    if (items.size() == limit) {
      pos.erase(items.back().first);
      items.pop_back();
    }
    items.emplace_front(key, std::move(value));
    try {
      pos.emplace(key, items.begin());
    } catch (...) {
      items.pop_front();
      throw;
    }
  }
};
